/**
 * Review: watches interactive input and renders either the "✏ Writing check"
 * widget (the prompt is in the learning language — fix mistakes) or the
 * "✏ Writing tutor" widget (the prompt is in the native language — teach the
 * words, grammar, and whole-sentence expression). A single LLM call decides
 * the mode, so the two are complementary and never both fire.
 *
 * Non-blocking by design — the message reaches the agent immediately and a
 * failed review never disturbs the session.
 */

import type { ExtensionAPI, ExtensionContext } from '@earendil-works/pi-coding-agent'
import { Container, Text } from '@earendil-works/pi-tui'
import { loadConfig } from './config.ts'
import type { Config, GrammarItem, ReviewResult } from './core.ts'
import { buildReviewPrompt, parseReviewResult, shouldSkipCheck } from './core.ts'
import { addCards, loadCards, saveCards } from './flashcards.ts'
import type { ForkContext } from './llm.ts'
import { resolveModel, runLlm } from './llm.ts'
import { showTutorWidget } from './tutor.ts'

const WIDGET_KEY = 'language-learn'

export interface ReviewDeps {
  /** Fork of the main session's last LLM request (see createForkTracker). */
  makeFork(ctx: ExtensionContext): ForkContext | undefined
}

function showCheckWidget(
  ctx: ExtensionContext,
  items: GrammarItem[],
  rephrase: string | undefined
): void {
  ctx.ui.setWidget(WIDGET_KEY, (_tui, theme) => {
    const container = new Container()
    container.addChild(new Text(theme.fg('accent', theme.bold('✏ Writing check')), 1, 0))
    for (const item of items) {
      const line = `${theme.fg('error', `"${item.wrong}"`)} → ${theme.fg('success', `"${item.right}"`)}  ${theme.fg('dim', item.reason)}`
      container.addChild(new Text(line, 1, 0))
    }
    if (rephrase) {
      container.addChild(new Text(`${theme.fg('dim', '◇')} ${theme.fg('muted', rephrase)}`, 1, 0))
    }
    return container
  })
}

/** Wire up the review. Returns `disable` for the settings toggle to call. */
export function registerReview(
  pi: ExtensionAPI,
  deps: ReviewDeps
): { disable(ctx: ExtensionContext): void } {
  let abort: AbortController | undefined

  const runReview = async (
    text: string,
    cfg: Config,
    ctx: ExtensionContext,
    signal: AbortSignal
  ) => {
    try {
      const model = resolveModel(ctx, cfg)
      if (!model) return

      const attempt = async (fork?: ForkContext): Promise<ReviewResult | undefined> => {
        const raw = await runLlm(ctx, model, buildReviewPrompt(text, cfg, !!fork), signal, fork)
        if (raw === undefined) return undefined
        const parsed = parseReviewResult(raw)
        // A forked reply that isn't the review JSON (the replayed agent
        // prompt won and the model answered as the agent) is a fork failure,
        // not a clean review; context-free garbage keeps the clear-widget
        // behavior below.
        if (parsed === undefined && fork) return undefined
        return parsed ?? { mode: 'skip' }
      }

      // Context mode must be strictly additive: a fork replay can fail in
      // ways a plain request can't (the model answers with a tool call or
      // as the agent in prose, the provider rejects the replayed prefix),
      // so on failure retry context-free.
      const fork = cfg.check === 'context' ? deps.makeFork(ctx) : undefined
      let result: ReviewResult | undefined
      try {
        result = await attempt(fork)
      } catch (err) {
        if (!fork || signal.aborted) throw err
      }
      if (result === undefined && fork && !signal.aborted) result = await attempt(undefined)
      if (signal.aborted || result === undefined) return

      if (result.mode === 'skip') {
        ctx.ui.setWidget(WIDGET_KEY, undefined)
        return
      }

      if (result.mode === 'tutor') {
        // The prompt already withholds tutor mode when it is disabled; this
        // guard covers a model that returns it anyway.
        if (cfg.tutor) {
          showTutorWidget(ctx, result.tutor)
          // Auto-capture vocabulary as flashcards (deduped by word)
          if (result.tutor.words.length > 0) {
            const cards = loadCards()
            const added = addCards(cards, result.tutor.words, 'tutor')
            if (added > 0) saveCards(cards)
          }
        } else {
          ctx.ui.setWidget(WIDGET_KEY, undefined)
        }
        return
      }

      // check
      const items = result.items
      const rephrase = result.rephrase ?? undefined
      if (items.length === 0 && !rephrase) {
        ctx.ui.setWidget(WIDGET_KEY, undefined)
      } else {
        showCheckWidget(ctx, items, rephrase)
      }

/**
 * Translation: renders assistant responses as bilingual cards (alt+t,
 * /t, and auto mode). Cards are custom entries — never sent back to
 * the LLM, costing no context.
 */

import type { ExtensionAPI, ExtensionContext } from '@earendil-works/pi-coding-agent'
import { getMarkdownTheme } from '@earendil-works/pi-coding-agent'
import { Box, Markdown, Text } from '@earendil-works/pi-tui'
import { loadConfig } from './config.ts'
import type { CardSegment, Config, Segment, TranslationCard } from './core.ts'
import {
  isOmpRuntime,
  assistantMessageText,
  buildSegmentPrompt,
  buildWholeTranslatePrompt,
  cardMarkdown,
  extractJson,
  finalAssistantReplyText,
  MAX_TRANSLATE_CHARS,
  MIN_AUTO_WORDS,
  segmentMarkdown,
  SHORT_CODE_LINES,
  translationLabel
} from './core.ts'
import type { ForkContext, ResolvedModel } from './llm.ts'
import { resolveModel, runLlm } from './llm.ts'
import { STATUS_KEY, updateStatus } from './settings.ts'

const ENTRY_TYPE = 'lang-translation'

/**
 * What Option+T types on macOS US/ABC layouts when the terminal keeps Option
 * as a text modifier instead of Alt; pi never sees it as alt+t.
 */
const MACOS_OPTION_T = '†'

export interface TranslateDeps {
  /** Fork of the main session's last LLM request, for context mode. */
  makeFork(ctx: ExtensionContext): ForkContext | undefined
}

/** Wire up bilingual translation: entry renderer, alt+t/option+t, /t, and auto mode. */
export function registerTranslation(pi: ExtensionAPI, deps: TranslateDeps): void {
  let lastAutoKey: string | undefined

  // omp renamed registerEntryRenderer -> registerMessageRenderer (same renderer
  // contract: receives the entry, options, and theme, returns a Component).
  type RenderTheme = {
    bg(color: string, text: string): string
    fg(color: string, text: string): string
    bold(text: string): string
  }
  const cardRenderer = (data: TranslationCard | undefined, theme: RenderTheme | undefined) => {
    if (!data) return undefined
    const markdown = data.segments ? cardMarkdown(data.segments) : data.text
    if (!markdown) return undefined
    const box = new Box(1, 0, (t) => theme?.bg('customMessageBg', t) ?? t)
    box.addChild(
      new Text(
        theme?.fg('accent', theme.bold(`🌐 ${translationLabel(data.native)}`)) ??
          `🌐 ${translationLabel(data.native)}`,
        0,
        0
      )
    )
    box.addChild(new Markdown(markdown, 0, 0, getMarkdownTheme()))
    return box
  }
  const isOmp = isOmpRuntime(pi)
  if (isOmp) {
    const omp = pi as {
      registerMessageRenderer<T>(
        type: string,
        r: (entry: { data?: T }, opts: unknown, theme: RenderTheme | undefined) => unknown
      ): void
    }
    omp.registerMessageRenderer<TranslationCard>(ENTRY_TYPE, (entry, _opts, theme) =>
      cardRenderer(entry.data, theme)
    )
  } else {
    pi.registerEntryRenderer<TranslationCard>(ENTRY_TYPE, (entry, _opts, theme) =>
      cardRenderer(entry.data, theme)
    )
  }

  const lastAssistantText = (ctx: ExtensionContext): string | undefined => {
    const branch = ctx.sessionManager.getBranch()
    for (let i = branch.length - 1; i >= 0; i--) {
      const entry = branch[i] as { type: string; message?: unknown }
      if (entry.type !== 'message') continue
      const text = assistantMessageText(entry.message)
      if (text) return text
    }
    return undefined
  }

  const buildBilingualSegments = async (
    source: string,
    cfg: Config,
    ctx: ExtensionContext,
    model: ResolvedModel,
    fork?: ForkContext
  ): Promise<CardSegment[] | undefined> => {
    const segments = segmentMarkdown(source)
    const prose = segments.filter((s): s is Segment & { kind: 'prose' } => s.kind === 'prose')
    if (prose.length === 0) return undefined

    const raw = await runLlm(
      ctx,
      model,
      buildSegmentPrompt(
        prose.map((p) => p.text),
        cfg,
        !!fork
      ),
      ctx.signal,
      fork
    )
    if (raw === undefined) return undefined
    const translations = extractJson<{ t?: unknown }>(raw)?.t
    if (
      !Array.isArray(translations) ||
      translations.length !== prose.length ||
      !translations.every((t) => typeof t === 'string')
    ) {
      return undefined
    }

    let proseIndex = 0
    return segments.map((s): CardSegment => {
      if (s.kind === 'prose') {
        return { kind: 'pair', src: s.text, dst: (translations[proseIndex++] as string).trim() }
      }
      return s.lines <= SHORT_CODE_LINES
        ? { kind: 'code', text: s.text }
        : { kind: 'codeRef', lines: s.lines }
    })
  }

  /**
   * Translate `opts.source`, or the last assistant message on the branch when
   * the caller has no text in hand (alt+t, /t).
   */
  const translateLast = async (
    ctx: ExtensionContext,
    opts?: { auto?: boolean; source?: string }
  ) => {
    if (!ctx.hasUI) return
    const cfg = loadConfig()
    const notify = (msg: string) => {
      if (!opts?.auto) ctx.ui.notify(msg, 'warning')
    }

    const source = opts?.source ?? lastAssistantText(ctx)
    if (!source) {
      notify('No assistant message to translate')
      return
    }

    const model = resolveModel(ctx, cfg)
    if (!model) {
      notify('No model available for translation (set one with /lang model)')
      return
    }

    ctx.ui.setStatus(STATUS_KEY, '🌐 translating…')
    try {
      const clipped = source.slice(0, MAX_TRANSLATE_CHARS)

      const attempt = async (fork?: ForkContext): Promise<boolean> => {
        const segments = await buildBilingualSegments(clipped, cfg, ctx, model, fork)
        if (segments) {
          pi.appendEntry<TranslationCard>(ENTRY_TYPE, { native: cfg.native, segments })
          return true
        }

        // Fallback: whole-text translation as a plain card.
        const translated = await runLlm(
          ctx,
          model,
          buildWholeTranslatePrompt(clipped, cfg, !!fork),
          ctx.signal,
          fork
        )
        if (!translated) return false
        pi.appendEntry<TranslationCard>(ENTRY_TYPE, { native: cfg.native, text: translated })
        return true
      }

      // Context mode must be strictly additive: a fork replay can fail in ways
      // a plain request can't (the model answers with a tool call, the provider
      // rejects the replayed prefix), so on failure retry context-free.
      const fork = cfg.context ? deps.makeFork(ctx) : undefined
      let done = false
      try {
        done = await attempt(fork)
      } catch (err) {
        if (!fork || ctx.signal?.aborted) throw err
      }

